import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.CxkNbRKf.js";const p=JSON.parse('{"title":"Install with Docker","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guide/installation-docker.md","filePath":"installation-guide/installation-docker.md","lastUpdated":1786379412000}'),i={name:"installation-guide/installation-docker.md"};function n(l,e,s,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="install-with-docker" tabindex="-1">Install with Docker <a class="header-anchor" href="#install-with-docker" aria-label="Permalink to &quot;Install with Docker&quot;">​</a></h1><p>Docker is a convenient way to run NADA locally or in a containerized environment without manually installing Apache/PHP/MySQL on the host.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p>An official-style Docker setup is maintained in a separate repository:</p><p><strong><a href="https://github.com/mah0001/nada-docker" target="_blank" rel="noreferrer">https://github.com/mah0001/nada-docker</a></strong></p><p>Follow that repository’s README for:</p><ul><li>Cloning the Docker project</li><li>Building / starting containers (<code>docker compose</code> or equivalent)</li><li>Default ports and URLs</li><li>Default credentials (change these before any shared or production use)</li></ul><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Install <a href="https://docs.docker.com/get-docker/" target="_blank" rel="noreferrer">Docker</a> (and Docker Compose if not bundled).</li><li>Review <a href="./#requirements">Requirements</a> so you understand what NADA needs inside the containers (PHP, database, etc.).</li><li>Prefer <strong>PHP 8.x</strong> images when the Docker project offers a choice; minimum supported PHP for NADA is <strong>7.4</strong>.</li></ul><h2 id="after-containers-are-up" tabindex="-1">After containers are up <a class="header-anchor" href="#after-containers-are-up" aria-label="Permalink to &quot;After containers are up&quot;">​</a></h2><ol><li>Open the NADA URL exposed by the compose file (see the Docker repo README).</li><li>Complete any first-run / installer steps if prompted.</li><li>Configure <a href="./configurations/email.html">email</a> and continue with <a href="/nada-documentation/getting-started/">Getting started</a>.</li></ol><p>For non-Docker installs, use the full platform guides: <a href="./platform-linux.html">Linux</a> · <a href="./platform-windows.html">Windows</a>.</p><div class="tip custom-block"><p class="custom-block-title">Production</p><p>Treat the Docker repo as a starting point. Harden credentials, volumes, networking, and HTTPS before production use.</p></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Installation</a> — non-Docker install</li><li><a href="./installation-git.html">Install with Git</a></li><li><a href="./debug.html">Debug</a></li></ul>',15)])])}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
